BEGIN;
DO $qa$
DECLARE c record; r record; d record; rb jsonb; ev jsonb; qa jsonb; released jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('saly:creative:serial:v1',0));
 SELECT * INTO STRICT r FROM saly.creative_runs WHERE id=12 AND order_id=22 AND item_id=26 AND attempt_number=4 AND state='EJECUTANDO' AND output_evidence='{}'::jsonb FOR UPDATE;
 SELECT * INTO STRICT c FROM saly.creative_queue_claims_v1 WHERE id=r.queue_claim_id AND order_id=22 AND item_id=26 AND state='ACTIVE' FOR UPDATE;
 SELECT * INTO STRICT d FROM saly.creative_queue_native_dispatch_reservations_v1 WHERE run_id=12 AND order_id=22 AND item_id=26 AND wire_sha256='1b28af9358a9a049240355114b98043424b31c6e60932bbb22174765a1fdf620' AND prompt_sha256='30ca33e69940a6b629377b21a40cdcf4b90952001e23d41030b89a10174092d5';
 ev:=$evidence${"artifact_ref":"chatgpt:file_000000006088820eacc477fd78cc8c7f","sha256":"3eb3807ad2133df988e94c74f834b393ade4fbda2b8468d4f7c3cdc187266450","worker_receipt":"HOST_OBSERVED_IMAGE_GEN:0fac1259-ed64-4823-9f14-501b8d757096","width":1086,"height":1448,"bytes":1549141,"mime_type":"image/png","handoff_status":"HANDOFF_SENT_UNVERIFIED","provider_receipt":null,"provider_attested":false,"source_sha256":"3d80592dc94938ea6e4d34727a99a0aec242b43838e2815820b72e87d649d33e","logo_source_sha256":"5573f0503ddb3dd1029221a9ee336d0e28155c392598286628dbf294da146995","source_bytes":1343036,"logo_source_bytes":150630,"native_prompt_byte_match_proven":false,"chat_delivery_observed":true}$evidence$::jsonb||jsonb_build_object('reservation_id',d.id,'reserved_wire_sha256',d.wire_sha256,'reserved_prompt_sha256',d.prompt_sha256);
 PERFORM saly.creative_queue_advance_run_v1(c.claim_token,12,'EXITOSO',ev,NULL);
 rb:=saly.creative_run_image_readback_v2(12,26);
 IF rb->>'status' IS DISTINCT FROM 'READY' OR rb->>'sha256' IS DISTINCT FROM ev->>'sha256' THEN RAISE EXCEPTION 'SALY_RUN12_READBACK_DRIFT'; END IF;
 qa:=$receipt${"review_mode":"GPT_SELF_QA","reviewer_kind":"AUTOMATED_MODEL","generator_model_family":"GPT","reviewer_model_family":"GPT","semantic_independence_proven":false,"verdict":"FAIL","comment":"6/6 visual. Logo, exactitud de CTA y escala de monto no conformes. Etiquetas de dos líneas: observación no bloqueante. No regenerar.","artifact_sha256":"3eb3807ad2133df988e94c74f834b393ade4fbda2b8468d4f7c3cdc187266450","design_qa_v1":{"visual_anchor":{"score":1,"evidence":"Monto dominante"},"single_hero":{"score":1,"evidence":"Una tarjeta con monto, fecha y CTA"},"semantic_active_colors_min_2":{"score":1,"evidence":"Verde acciones, navy información"},"balanced_space":{"score":1,"evidence":"Cuatro círculos separados"},"cta_anchored_or_not_applicable":{"score":1,"evidence":"CTA dentro de tarjeta"},"max_3_accents":{"score":1,"evidence":"Verde/navy/blanco visuales"}},"checklist_results":{"sin_banner":{"verdict":"PASS","evidence":"No banner ni carrusel"},"una_imagen":{"verdict":"PASS","evidence":"Un PNG asociado al RUN 12"},"escala_real":{"verdict":"FAIL","evidence":"Pantalla aproximada 655 px; CTA 77 px equivale a 46.2 pt; monto caja tinta 361x76 px equivale a 216.6x45.6 pt, altura supera 34 pt"},"monto_literal":{"verdict":"PASS","evidence":"S/ 575.00"},"slot_variable":{"verdict":"PASS","evidence":"Cuatro accesos diferenciados; dinámica no verificable en PNG"},"tokens_active":{"verdict":"FAIL","evidence":"Moda CTA RGB(7,133,1) #078501, distinta de #008200"},"textos_exactos":{"verdict":"PASS","evidence":"Textos funcionales visibles"},"max_tres_acentos":{"verdict":"PASS","evidence":"Verde/navy/blanco"},"sin_textos_extra":{"verdict":"PASS","evidence":"Sin subtítulo"},"logo_oficial_asset_id":{"verdict":"FAIL","evidence":"Original SHA verificado; IoU máscaras normalizadas 0.7084; proporción ancho/alto original 1.626 vs render 1.541; composición exacta no acreditada"},"accesos_sin_duplicados":{"verdict":"PASS","evidence":"Historial únicamente en navegación"},"accesos_circulares_espaciados":{"verdict":"PASS","evidence":"Cuatro círculos separados"}},"preflight":{"verdict":"FAIL","evidence":"Reserva y fuentes verificadas; transporte literal y composición protegida no acreditados"},"observations":["Etiquetas en dos líneas aceptadas como observación no bloqueante.","Teléfono aproximadamente 718 px, 66.1% del lienzo; pantalla 655 px. CTA 77 px, 11.8% del ancho de pantalla; monto 361 px, 55.1%.","No intento adicional."]}$receipt$::jsonb||jsonb_build_object('reviewer_ref',c.worker_ref,'run_id',12,'readback',rb);
 UPDATE saly.creative_order_items SET status='BLOQUEADO',qa_receipt=qa WHERE id=26 AND order_id=22 AND status='PRODUCIENDO';
 IF NOT FOUND THEN RAISE EXCEPTION 'SALY_RUN12_QA_ITEM_NOT_PRODUCING'; END IF;
 released:=saly.creative_queue_release_v1(c.claim_token,'BLOCKED','QA_FAIL: logo, exact token, scale; no further attempt authorized');
 IF released->>'status' IS DISTINCT FROM 'RELEASED' THEN RAISE EXCEPTION 'SALY_RUN12_QA_RELEASE_FAILED'; END IF;
 RAISE NOTICE 'SALY_RUN12_READBACK % QA FAIL CLAIM BLOCKED',rb->>'status';
END $qa$;
COMMIT;
